def test_three_rewards():
    assert abs(solution.discounted_return([1.0, 1.0, 1.0], 0.5) - 1.75) < 1e-12

def test_single_reward():
    assert solution.discounted_return([2.0], 0.9) == 2.0

def test_gamma_zero_keeps_only_first():
    assert solution.discounted_return([3.0, 9.0, 9.0], 0.0) == 3.0

def test_late_big_reward_is_small():
    rewards = [0.0] * 100 + [11.0]
    got = solution.discounted_return(rewards, 0.9)
    assert got < 1.0
    assert got > 0.0

def test_bad_gamma_raises():
    for g in (-0.1, 1.1):
        try:
            solution.discounted_return([1.0], g)
        except ValueError:
            continue
        raise AssertionError("expected ValueError for gamma=%r" % (g,))

def test_empty():
    assert solution.discounted_return([], 0.9) == 0.0
